export const byId=Object.fromEntries(steps.map(s=>[s.id,s]));
export function blockers(step,done={}){return step.deps.filter(id=>!done[id]);}
export function nextStep(node,done={}){return steps.find(s=>s.node===node&&!done[s.id]);}
export function cascade(id,done){const affected=new Set([id]);let changed=true;while(changed){changed=false;for(const s of steps)if(done[s.id]&&!affected.has(s.id)&&s.deps.some(d=>affected.has(d))){affected.add(s.id);changed=true;}}return [...affected].filter(x=>done[x]);}
export function commandFor(step,config={},origin='https://YOUR-VERCEL-SITE.vercel.app'){const vars={origin,network:config.network||'<ZEROTIER_NETWORK_ID>',user:config.user||'ubuntu',...Object.fromEntries([1,2,3,4].map(n=>[`ip${n}`,config[`ip${n}`]||`<NODE_${n}_PRIVATE_IP>`]))};return step.command.replace(/\{\{(\w+)\}\}/g,(_,k)=>vars[k]??'');}
